        if exists(camp_r):
            attack(camp_r)
        set_priority( 1 + random_int(100) )
        end_turn()
if exists(goal) and distance(position(), goal) > 2 and fuel_remaining() > 55000:
    dash_to(0, goal)
    dash_to(1, goal)
if has_teleport() and exists(goal) and distance(position(), goal) > 0 and distance(position(), goal) <= 3 and count(foes) == 0:
    teleport_to(goal)
    end_turn()
if count(foes) == 0 and contains( bushes(), position() ):
    place_ward( position() )
# announce the group we walk to so partners can see it (claim)
if exists(goal):
    claim(goal)
move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()

# PLAN (ability axis):
# 1. Stun first: when a foe is in reach, spend the turn on a ready stun slot (slot_stun > 0) before any damage slot, since one ability is cast per turn.
# 2. Dash opener (new): a ready stunning dash that can reach the target (within its range plus 1) is cast first, so the stun lands on hit and the same turn's stun or damage follows. Fuel-gated.
# 3. AoE and range: aoe slots are cast at the target tile to catch clustered foes; every cast checks slot_range so no ability is wasted out of reach.
# 4. Allies: a heal slot goes to the weakest visible ally under 40% health; a shield slot is used when we are under 50% health in a fight.
# 5. Reset: after the first basic attack, a reset slot is cast and attacks repeat, as in v0.
# 6. Economy, camp, tribute and vision logic are unchanged from v1; only the strike helper changes.

def can_hit(slot, u):
    return ability_ready(slot) and not slot_is_dash(slot) and not slot_is_shield(slot) and not slot_is_heal(slot) and not slot_is_reset(slot) and distance(position(), unit_position(u)) <= slot_range(slot)

def strike(u):
    # opener: a ready stunning dash that reaches the target (fuel guarded), so the stun lands on hit
    if fuel_remaining() > 50000 and ability_ready(0) and slot_is_dash(0) and slot_stun(0) > 0 and distance(position(), unit_position(u)) <= slot_range(0) + 1:
        dash_towards(0, unit_position(u))
    elif fuel_remaining() > 50000 and ability_ready(1) and slot_is_dash(1) and slot_stun(1) > 0 and distance(position(), unit_position(u)) <= slot_range(1) + 1:
        dash_towards(1, unit_position(u))
    # stun first (stun before burst), then any other damage or AoE slot, all within slot range
    if can_hit(0, u) and slot_stun(0) > 0:
        if slot_is_aoe(0):
            cast_at_tile(0, unit_position(u))
        else:
            cast_at_unit(0, u)
    elif can_hit(1, u) and slot_stun(1) > 0:
        if slot_is_aoe(1):
            cast_at_tile(1, unit_position(u))
        else:
            cast_at_unit(1, u)
    elif can_hit(0, u):
        if slot_is_aoe(0):
            cast_at_tile(0, unit_position(u))
        else:
            cast_at_unit(0, u)
    elif can_hit(1, u):
        if slot_is_aoe(1):
            cast_at_tile(1, unit_position(u))
        else:
            cast_at_unit(1, u)

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vendetta()):
        pick(champ_vendetta())
    elif available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_tavi()):
        pick(champ_tavi())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    elif available(pool, champ_ren()):
        pick(champ_ren())
    else:
        pick( random_champion(pool) )
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()
# monolith groups never change: one group_tiles() per game (fuel; bot-session check)
keep mono_groups = group_tiles( monolith_tiles() )
keep altar_ring = ring( altars(), 1 )
keep safe_altar_ring = ring( minus( altars(), ring(monolith_tiles(), 5) ), 1 )

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains( spawn_region(ally()), position() )
# one enemies_visible() query per turn, reused below (no move happens before its last use)
let foes = enemies_visible()
if at_spawn:
    let shards_bought = floor( gold() / 30 )
    let treasure_n = floor( shards_bought / 2 )
    let rest_after_treasure = shards_bought - treasure_n
    let jungle_n = floor( rest_after_treasure / 2 )
    let rest_after_jungle = rest_after_treasure - jungle_n
    let strength_shards = floor( rest_after_jungle / 2 )
    buy( shard_of(family_treasure(), stat_strength()), treasure_n )
    buy( shard_of(family_jungle(), stat_health()), jungle_n )
    buy( shard(stat_strength()), strength_shards )
    buy( shard(stat_health()), rest_after_jungle - strength_shards )
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(foes, in_attack_range()))):
        end_turn()

# retreat at 30% health normally
# safe recall (tune line): never start a recall with an enemy champion within 8; retreat first, recall when clear
if not at_spawn and health() < 0.3 * max_health():
    if (in_danger() or enemies_within(8) > 0):
        let home = closest( spawn_region(ally()) )
        # fuel gate: a long retreat's dash search can push the turn past 100k
        if fuel_remaining() > 60000:
            dash_to(0, home)
            dash_to(1, home)
        move_towards(home)
        end_turn()
    recall()
    end_turn()
if not at_spawn and gems() > 0 and health() < 0.5 * max_health() and not (in_danger() or enemies_within(8) > 0):
    recall()
    end_turn()

# CAST-AHEAD: stun or damage a close enemy champion before it reaches us
if exists( first(foes) ):
    let near_foe = nearest( foes )
    if exists(near_foe) and distance(position(), unit_position(near_foe)) <= 4 and not contains( spawn_region(enemy()), unit_position(near_foe) ):
        set_team_target(near_foe)
        strike(near_foe)

# ---- COMBAT MICRO ----
# nearest visible enemy (threat for kiting and disengaging)
let threat = nearest(foes)

# disengage: outnumbered locally, so step away instead of trading (no attack this turn)
if count(foes) >= 2 and local_strength(5) < 0.7 and not at_spawn:
    move_away_from( unit_position(threat) )
    end_turn()

# kiting: a ranged champion with an enemy adjacent steps back before shooting
if i_am_ranged() and can_move() and distance(position(), unit_position(threat)) <= 1:
    move_away_from( unit_position(threat) )

let inrange = filter( foes, in_attack_range() )
let enemy = weakest( inrange )

# support abilities in a fight: heal the weakest hurt ally in range, shield ourselves when low
if exists(first(foes)):
    let hurt = weakest( allies_visible() )
    if exists(hurt) and unit_health_frac(hurt) < 0.4:
        if ability_ready(0) and slot_is_heal(0) and distance(position(), unit_position(hurt)) <= slot_range(0):
            cast_at_unit(0, hurt)
        elif ability_ready(1) and slot_is_heal(1) and distance(position(), unit_position(hurt)) <= slot_range(1):
            cast_at_unit(1, hurt)
    if health() < 0.5 * max_health():
        if ability_ready(0) and slot_is_shield(0):
            cast_self(0)
        elif ability_ready(1) and slot_is_shield(1):
            cast_self(1)

# focus fire: if the team's focus target is in our reach, hit it instead of the weakest
let tt = team_target()
let tt_d = distance( position(), unit_position(tt) )
if (tt_d <= 1 or (tt_d <= 3 and i_am_ranged())) and not contains( spawn_region(enemy()), unit_position(tt) ):
    strike(tt)
    attack(tt)
    # attack reset: a second basic attack after the first (it does nothing before one)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(tt)
    end_turn()

# an enemy on its own spawn is healed every turn: fighting it there never ends (00reverse-spiral)
if exists(enemy) and not contains( spawn_region(enemy()), unit_position(enemy) ):
    # publish the target so allies converge on the same turn
    set_team_target(enemy)
    strike(enemy)
    attack(enemy)
    # attack reset: a second basic attack after the first (it does nothing before one)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(enemy)
    end_turn()

# tribute only with a worthwhile bag (or when hurt / late game)
let bag_ready = gems() >= 25 or round_number() > 1500 or health() < 0.3 * max_health()
if gems() > 0 and bag_ready:
    # an altar next to us works even when locked: tributing there attacks the lock (5 hits clear it)
    let altar = first( filter( altars(), within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    # walk to an open altar out of monolith reach (5); else any altar out of reach; else any altar
    let target = closest( minus( safe_altar_ring, ring(locked_altars(), 1) ) )
    if exists(target):
        move_towards(target)
        end_turn()
    let target2 = closest(safe_altar_ring)
    if exists(target2):
        move_towards(target2)
        end_turn()
    let altar_goal = closest(altar_ring)
    # every altar-adjacent tile is taken by a camp: fight it
    if contains(camp_spawns, altar_goal):
        let blocker = first( filter( camps_visible(), in_attack_range() ) )
        if exists(blocker):
            attack(blocker)
            end_turn()
    move_towards( altar_goal )
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    cast_on(0, camp)
    cast_on(1, camp)
    attack(camp)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(camp)
    end_turn()

# nothing tributed by round 800: go for monoliths too
if team_score(ally()) == 0 and round_number() > 800:
    move_towards( closest( minus( minus( camp_spawns, respawning_visible_spawns() ), golem_tiles() ) ) )
    end_turn()
let goals = minus( minus( minus( minus( camp_spawns, respawning_visible_spawns() ), monolith_tiles() ), golem_tiles() ), mono_groups )

# already standing on a cleared camp spawn: hold here so the capture timer keeps running
if contains(capturable_spawns(), position()):
    end_turn()

let goal = closest(goals)
# bank before a dangerous group (elk 60, wolf 20 per camp)
if exists(goal) and gems() >= 10 and group_threat(goal) >= 240 and fuel_remaining() > 65000:
    let bank_altar = first( filter( altars(), within(1, position()) ) )
    if exists(bank_altar):
        tribute(bank_altar)
        end_turn()
    move_towards( closest(safe_altar_ring) )
    end_turn()
# on a dead camp of a group not yet cleared: walk to the nearest living camp (not a monolith or golem)
if distance(goal, position()) == 0:
    let live = nearest(camps)
    if exists(live) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(live) ):
        move_towards( unit_position(live) )
        end_turn()
# dash toward a camp goal only when farther than 2 (fuel guarded)
if exists(goal) and distance(position(), goal) > 2 and fuel_remaining() > 55000:
    dash_to(0, goal)
    dash_to(1, goal)
# VISION: no enemy in sight and standing in a bush: ward our own tile to hide the walk
if count(foes) == 0 and contains( bushes(), position() ):
    place_ward( position() )
move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()
